for e in '${#u}' '${u/x/y}' '${u:1}' '${u@Q}' '${u@a}' '${u^}' '${u,,}' '${u#x}' '${u%x}' '${#a[@]}' '${a[@]}' '${a[*]}' '${a[0]}' '${#a[0]}' '${!a[@]}' '${!u}' '${!pre*}' '${u-d}' '${u:-d}' '${u+d}' '${u:+d}' '$1' '${1}' '$@' '$*' '${#@}' '${#}' '$#' '${@:1}' '${e[@]}' '${#e[@]}' '${e[0]}' '${e[@]:0}' '${!e[@]}' '${A[k]}' '${#A[@]}' '${u@P}' '${u[@]}' '${u[*]}' '$!' '$$x' '${LINENO}' '${u:-$v}' '$((u+1))' '${#u[@]}' '${u[1]:-x}' '${#A[k]}'; do
  r=$($SH -c "set -u; e=(); declare -A A; echo \"[$e]\"; echo st=\$?" 2>&1 | sed "s|^[a-z/]*: line 1: |X: |" | tr '\n' ' ')
  printf '%-14s %s\n' "$e" "$r"
done
